!function(){"use strict";document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".header");if(!e)return;let t=window.scrollY;window.addEventListener("scroll",()=>{const d=window.scrollY;if(d<=0)return e.classList.remove("header-hidden"),void(t=d);Math.abs(d-t)<10||(d>t?e.classList.add("header-hidden"):e.classList.remove("header-hidden"),t=d)},{passive:!0})}),document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".header");if(!e)return;const t=()=>{document.documentElement.style.setProperty("--header-height",`${e.offsetHeight}px`)};t(),window.addEventListener("resize",t)})}();